INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a55ece240446b48d513c','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','363','Mixed/Unclassified','MCQ 3.320
A 26-year-old woman presents for an antenatal visit in her first pregnancy which
has been progressing normally. Her routine mid-trimester ultrasound examination,
performed at 18 weeks of gestation, shows that the placenta occupies the lower part
of the uterus, reaching to within 1cm of the internal cervical os. She asks you about
the implications of this finding, and the subsequent management necessary. Which
one of the following would be the most appropriate advice?
A. Repeated cardiotocographic (CTG) monitoring of the fetus from 32 weeks
onwards.
Repeat the ultrasound examination in 4 weeks’ time.
. Repeat the ultrasound at 34 weeks of gestation.
Repeat the ultrasound at term.
Recommend delivery by Caesarean section.
Mm OQ; 2:
MCQ 3.321
An 18-year-old woman presents for her first antenatal visit. She had always had regular
menstrual cycles, both when she was or was not taking the oral contraceptive pill
(OCP). She ceased the OCP 20 weeks ago, had a period within a few days of this, but
has had no further vaginal bleeding since that time, and has not noticed any fluid loss
from her vagina. On clinical examination the uterus is palpable just above the pubic
symphysis. Fetal heart beats could be heard with a hand-held Doppler device. Which
one of the following is the most likely explanation for the discrepancy between the
dates and uterine size?
Oligohydramnios with intact membranes.
The fetus is malformed.
. The fetus is growth-restricted.
The membranes have ruptured.
Ovulation did not occur until 6-8 weeks after her last period.
MOQO2>
MCQ 3.322
A 26-year-old woman, whose first baby was delivered at 39 weeks of gestation,
presents because she has been having irregular uterine contractions for the preceding
24 hours, and is concerned this baby will be delivered prematurely. She is currently at
26 weeks of gestation in her second pregnancy. Her BP and urinalysis are normal, and
abdominal examination shows the symphysis-fundal height is 27cm, the uterus is lax
and non-tender and the fetal heart rate is audible at 150/min. Pelvic examination is
then performed, as are a number of investigations. Which one of the following findings
would indicate that delivery is most likely to occur before 30 weeks of gestation?','{"A":"The external cervical os admits the finger-tip, but the internal os is closed.","B":"The cervix is closed, but the vaginal swab shows evidence of bacterial vaginosis.\n. The cervix is 3.8cm long on ultrasound examination.","C":"The cervix is closed, but the fetal fibronectin test on cervical secretions is positive.\nThe cervix is closed, but a cervical swab reveals Candida albicans is present.","D":"MOQ2>","E":"Australian Medical Council\nSection 3 — Maternal Health"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[363],"source_qid":"3.320","duplicate_group_id":"exact-7fbf7894e791","duplicate_sources":[{"record_id":"a55ece240446b48d513c","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":363,"source_qid":"3.320"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"a55ece240446b48d513c","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":363,"supporting_pages":[363],"source_qid":"3.320","domain_hint":"Mixed/Unclassified","stem":"MCQ 3.320\nA 26-year-old woman presents for an antenatal visit in her first pregnancy which\nhas been progressing normally. Her routine mid-trimester ultrasound examination,\nperformed at 18 weeks of gestation, shows that the placenta occupies the lower part\nof the uterus, reaching to within 1cm of the internal cervical os. She asks you about\nthe implications of this finding, and the subsequent management necessary. Which\none of the following would be the most appropriate advice?\nA. Repeated cardiotocographic (CTG) monitoring of the fetus from 32 weeks\nonwards.\nRepeat the ultrasound examination in 4 weeks’ time.\n. Repeat the ultrasound at 34 weeks of gestation.\nRepeat the ultrasound at term.\nRecommend delivery by Caesarean section.\nMm OQ; 2:\nMCQ 3.321\nAn 18-year-old woman presents for her first antenatal visit. She had always had regular\nmenstrual cycles, both when she was or was not taking the oral contraceptive pill\n(OCP). She ceased the OCP 20 weeks ago, had a period within a few days of this, but\nhas had no further vaginal bleeding since that time, and has not noticed any fluid loss\nfrom her vagina. On clinical examination the uterus is palpable just above the pubic\nsymphysis. Fetal heart beats could be heard with a hand-held Doppler device. Which\none of the following is the most likely explanation for the discrepancy between the\ndates and uterine size?\nOligohydramnios with intact membranes.\nThe fetus is malformed.\n. The fetus is growth-restricted.\nThe membranes have ruptured.\nOvulation did not occur until 6-8 weeks after her last period.\nMOQO2>\nMCQ 3.322\nA 26-year-old woman, whose first baby was delivered at 39 weeks of gestation,\npresents because she has been having irregular uterine contractions for the preceding\n24 hours, and is concerned this baby will be delivered prematurely. She is currently at\n26 weeks of gestation in her second pregnancy. Her BP and urinalysis are normal, and\nabdominal examination shows the symphysis-fundal height is 27cm, the uterus is lax\nand non-tender and the fetal heart rate is audible at 150/min. Pelvic examination is\nthen performed, as are a number of investigations. Which one of the following findings\nwould indicate that delivery is most likely to occur before 30 weeks of gestation?","options":{"A":"The external cervical os admits the finger-tip, but the internal os is closed.","B":"The cervix is closed, but the vaginal swab shows evidence of bacterial vaginosis.\n. The cervix is 3.8cm long on ultrasound examination.","C":"The cervix is closed, but the fetal fibronectin test on cervical secretions is positive.\nThe cervix is closed, but a cervical swab reveals Candida albicans is present.","D":"MOQ2>","E":"Australian Medical Council\nSection 3 — Maternal Health"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","contracept","management","pregnan"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"7fbf7894e791b4e0737947203de6f59da446cd64","duplicate_group_id":"exact-7fbf7894e791","duplicate_sources":[{"record_id":"a55ece240446b48d513c","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":363,"source_qid":"3.320"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,impo