INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('9a88fe5259ea744df7fa','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','367','Mixed/Unclassified','Australian Medical Council
Section 3— Mental Health
MCQ 3.327
A 28-year-old investment banker presents for advice and treatment of persistent
premature ejaculation which he attributes to fatigue from his job and his new
relationship. Which one of the following would be the best approach for his longterm
benefit?','{"A":"Interview him with his partner.","B":"Teach him relaxation exercises.","C":"Instruct him in the use of penile squeeze techniques.","D":"Prescribe sildenafil (Viagra®) one hour before attempting intercourse.","E":"Prescribe low dose clomipramine.\n\nMCQ 3.328\nA 21-year-old medical student presents with a one-week history of increasing arousal\nand hypervigilance. He reports that he is God and describes ‘believing’ this when he\nfirst put on a white coat three weeks ago. This abnormal belief is an example of which\none of the following?\n\nAn illusion.\n\nAn hallucination.\n\n. Apassivity phenomenon.\n\nA delusional perception.\n\nThought insertion.\n\nMOQ2>\n\nMCQ 3.329\n\n} A 42-year-old academic has sought help from you for alcohol abuse. The most\nstriking feature is his lack of emotional warmth and rapport. He tells you he has never\nmarried and has no friends, but is devoted to his work as a research economist. His\nonly interest is playing fantasy games and chess on his home computer. He describes\nhimself as introspective and self-sufficient, and has always been aloof and ill at ease\nwith people, even his family of origin. Which one of the following is the most likely\ndisorder of his personality?\n\nAntisocial.\nSchizotypal.\n. Schizoid.\nAvoidant.\nParanoid.\n\nMmOQR>\n\nMCQ 3.330\n\nAs part of the mental state assessment of cognitive function, patients may be asked\nto subtract seven from 100 sequentially (‘serial sevens’). This ‘serial sevens’ test is\nprimarily a test of which one of the following?\n\nRegistration.\n\nDigit span.\n\n. Concentration.\nAbstract thinking.\n\nee Mal\n| (BE\n\nMmOOP>"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.327","duplicate_group_id":"exact-12ea7f203161","duplicate_sources":[{"record_id":"9a88fe5259ea744df7fa","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":367,"source_qid":"3.327"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"9a88fe5259ea744df7fa","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":367,"source_qid":"3.327","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 3— Mental Health\nMCQ 3.327\nA 28-year-old investment banker presents for advice and treatment of persistent\npremature ejaculation which he attributes to fatigue from his job and his new\nrelationship. Which one of the following would be the best approach for his longterm\nbenefit?","options":{"A":"Interview him with his partner.","B":"Teach him relaxation exercises.","C":"Instruct him in the use of penile squeeze techniques.","D":"Prescribe sildenafil (Viagra®) one hour before attempting intercourse.","E":"Prescribe low dose clomipramine.\n\nMCQ 3.328\nA 21-year-old medical student presents with a one-week history of increasing arousal\nand hypervigilance. He reports that he is God and describes ‘believing’ this when he\nfirst put on a white coat three weeks ago. This abnormal belief is an example of which\none of the following?\n\nAn illusion.\n\nAn hallucination.\n\n. Apassivity phenomenon.\n\nA delusional perception.\n\nThought insertion.\n\nMOQ2>\n\nMCQ 3.329\n\n} A 42-year-old academic has sought help from you for alcohol abuse. The most\nstriking feature is his lack of emotional warmth and rapport. He tells you he has never\nmarried and has no friends, but is devoted to his work as a research economist. His\nonly interest is playing fantasy games and chess on his home computer. He describes\nhimself as introspective and self-sufficient, and has always been aloof and ill at ease\nwith people, even his family of origin. Which one of the following is the most likely\ndisorder of his personality?\n\nAntisocial.\nSchizotypal.\n. Schizoid.\nAvoidant.\nParanoid.\n\nMmOQR>\n\nMCQ 3.330\n\nAs part of the mental state assessment of cognitive function, patients may be asked\nto subtract seven from 100 sequentially (‘serial sevens’). This ‘serial sevens’ test is\nprimarily a test of which one of the following?\n\nRegistration.\n\nDigit span.\n\n. Concentration.\nAbstract thinking.\n\nee Mal\n| (BE\n\nMmOOP>"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["treatment"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"12ea7f203161927fa7d3dc735bb7c2eb6299af2b","duplicate_group_id":"exact-12ea7f203161","duplicate_sources":[{"record_id":"9a88fe5259ea744df7fa","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":367,"source_qid":"3.327"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,