INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('0a28b9468e36eb1ce790','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','368','Mixed/Unclassified','Australian Medical Council
Section 3 — Mental Health
MCQ 3.331
A 32-year-old woman presents seeking counselling after the newsagency in —
which she works was robbed by a man with a knife who threatened her and
a customer. She is now anxious and hypervigilant and her sleep has become
disrupted by nightmares of the incident. She is adamant that she does not
want medication but asks about the outcome of the counselling. Which
one of the following would be the ultimate goal of her crisis intervention
counselling?
. To bring about a life-long change in her personality.
To restore her to her pre-crisis level of functioning.
. To promote a cathartic retelling of her experience.
. To facilitate her subsequent referral for longterm psychotherapy.
To provide emotional support during natural healing in response to stress.
M26) 7G); Oe
MCQ 3.332
A 24-year-old fashion model and minor celebrity presents after having used cocaine
at a party a few days ago. She has been ‘high’ and appears euphoric, elevated,
hyperactive and restless. Her urinary drug screen is negative. She insists that this is
just an exaggeration of her normal self and that she is usually quite emotional, with
short-lived highs and lows, tantrums and tears, which is corroborated by her partner.
She is quite concerned about her physical appearance and demands a mirror so
that she can ‘look right’ during your interview and touch up her face with make
up and lipstick before she speaks with you. During the interview she is disinhibited
and flirtatious, flatters you with compliments and asks you out on a date. Her mental
state examination is otherwise normal. Which one of the following is the most likely
diagnosis?
. Cocaine intoxication.
Undisclosed ecstasy usage.
. Histrionic personality disorder.
Cyclothymia.
Hypomania.
TOQRP>
MCQ 3.333
You have been visited in your general practice by a pharmaceutical company
representative accompanied by a researcher from the local university''s department
of clinical pharmacology. They request that you recommend and refer patients
from your general practice with insomnia who would be considered for a trial of a
new non-benzodiazepine hypnotic. Which one of the following is essential for your
agreement?','{"A":"Clarifying the sample size and the number needed to treat.","B":"Establishing the known side effect profile of the drug from earlier clinical trials.","C":"Verifying that the study has approval from a Human Research Ethics Committee.","D":"Ensuring that your patients receive adequate financial compensation for their\nparticipation.","E":"Insisting that you have co-authorship of any scientific papers that may result from\nthe study."}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.331","duplicate_group_id":"exact-96a324e0ac8b","duplicate_sources":[{"record_id":"0a28b9468e36eb1ce790","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":368,"source_qid":"3.331"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"0a28b9468e36eb1ce790","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":368,"source_qid":"3.331","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 3 — Mental Health\nMCQ 3.331\nA 32-year-old woman presents seeking counselling after the newsagency in —\nwhich she works was robbed by a man with a knife who threatened her and\na customer. She is now anxious and hypervigilant and her sleep has become\ndisrupted by nightmares of the incident. She is adamant that she does not\nwant medication but asks about the outcome of the counselling. Which\none of the following would be the ultimate goal of her crisis intervention\ncounselling?\n. To b