INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('c6092ac8409dcdc5610e','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','371','Mixed/Unclassified','An individual has the following personality characteristics: a pervasive and persistent
pattern of behaviour characterised by a grandiose sense of self importance; is
arrogant and is preoccupied with fantasies of unlimited success; believes that he
or she is special and unique; and has a strong sense of entitlement and shamelessly
exploits others yet lacks empathy for their feelings and needs. These characteristics
would satisfy diagnostic criteria for which one of the following personality disorders?
Histrionic.
Antisocial.
. Borderline.
Narcissistic.
Schizotypal.
TMOQRP>
MCQ 3.342
A previously healthy 19-year-old woman presents with a 10kg weight loss and poor
sleep following the death of her father six months earlier. She appears despondent
and cries when you ask her about her father. Which one of the following is the most
important to ask her about?
. Her relationship with her father.
Thoughts of suicide.
. Her eating patterns and nutritional intake.
. Her use of alcohol and other drugs.
A history of child sexual abuse.
MOQ 2 >
MCQ 3.343
A university tutor tells you about a young man in his class who has schizophrenia. He is
worried that there may be others, as he has read recently that use of illicit substances
is causing more cases of schizophrenia in the community. There are about 100
students in the class. Which one of the following applies to knowledge of the ‘point
prevalence’ of schizophrenia?','{"A":"New cases of schizophrenia are occurring more frequently.","B":"At this time, it is unlikely there are any other cases of schizophrenia in this class.","C":"The class members who use illicit substances will have an increased lifetime risk of\nschizophrenia.","D":"Over the next year a second student may present with symptoms. of\nschizophrenia.","E":"About three members of the class will have ever had a psychotic illness.\n\nMCQ 3.344\n\nA 40-year-old school teacher with major depression has been advised he needs\nelectroconvulsive therapy (ECT). He has good insight into the nature of his depression\nand the need for treatment. Which one of the following would be the most appropriate\nadvice to give him when obtaining consent for the ECT\n\nAusiralian Medical Council\n\nSection 3- Mental Health"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.341","duplicate_group_id":"exact-1ff412547f9f","duplicate_sources":[{"record_id":"c6092ac8409dcdc5610e","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":371,"source_qid":"3.341"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"c6092ac8409dcdc5610e","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":371,"source_qid":"3.341","domain_hint":"Mixed/Unclassified","stem":"An individual has the following personality characteristics: a pervasive and persistent\npattern of behaviour characterised by a grandiose sense of self importance; is\narrogant and is preoccupied with fantasies of unlimited success; believes that he\nor she is special and unique; and has a strong sense of entitlement and shamelessly\nexploits others yet lacks empathy for their feelings and needs. These characteristics\nwould satisfy diagnostic criteria for which one of the following personality disorders?\nHistrionic.\nAntisocial.\n. Borderline.\nNarcissistic.\nSchizotypal.\nTMOQRP>\nMCQ 3.342\nA previously healthy 19-year-old woman presents with a 10kg weight loss and poor\nsleep following the death of her father six months earlier. She appears despondent\nand cries when you ask her about her father. Which one of the following is the most\nimportant to ask her about?\n. Her relationship with her father.\nThoughts of suicide.\n. Her eating patterns and nutritional intake.\n. Her use of alcohol and other drugs.\nA history of child sexual abuse.\nMOQ 2 >\nMCQ 3.343\nA university tutor tells you about a young man in his class who has schizophrenia. He is\nworried that there may be others, as he has read recently that use of illicit substances\nis causing more cases of schizophrenia in the community. There are about 100\nstudents in the class. Which one of the following applies to knowledge of the ‘point\nprevalence’ of schizophrenia?","options":{"A":"New cases of schizophrenia are occurring more frequently.","B":"At this time, it is unlikely there are any other cases of schizophrenia in this class.","C":"The class members who use illicit substances will have an increased lifetime risk of\nschizophrenia.","D":"Over the next year a second student may present with symptoms. of\nschizophrenia.","E":"About three members of the class will have ever had a psychotic illness.\n\nMCQ 3.344\n\nA 40-year-old school teacher with major depression has been advised he needs\nelectroconvulsive therapy (ECT). He has good insight into the nature of his depression\nand the need for treatment. Which one of the following would be the most appropriate\nadvice to give him when obtaining consent for the ECT\n\nAusiralian Medical Council\n\nSection 3- Mental Health"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["drug"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"1ff412547f9f7db82096f292340546ebbae71817","duplicate_group_id":"exact-1ff412547f9f","duplicate_sources":[{"record_id":"c6092ac8409dcdc5610e","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":371,"source_qid":"3.341"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
