INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('fafe81e297581704a708','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','372','Mixed/Unclassified','Ausiralian Medical Council
Section 3 - Mental Health','{"A":"Reports of memory loss after ECT are exaggerated.","B":"ECT is superior to alternate therapies in most forms of depression.","C":"His family will also need to provide consent.","D":"ECT has good evidence for its efficacy from controlled trials.","E":"Consent will need to be obtained from a mental health tribunal or similar.\n\nMCQ 3.345\n\nSome factors increase the risk for more than one psychiatric disorder. Depression,\nanxiety, substance use and eating disorders may all have which one of the following\nas a risk factor?\n\nPerfectionism and obsessional traits.\nWorking in a bar (selling alcohol).\n\n. Sexual abuse in childhood.\n\nFamily history of autism.\n\nHistory of intellectual developmental delay.\n\nMOQOR>\n\nMCQ 3.346\n\nA 72-year-old man complains of waking in the middle of the night and not\nbeing able to get back to sleep. This has been happening now for months. He\nalso has a persistent headache, generalised aches and pains and constant\ntiredness. He has stopped going out and now spends most of his time at\nhome. Of the following, which one is the most important feature of the history\nto obtain from this patient?\n\nPrevious forensic history.\n\nAnxiety and panic attacks.\n\n. Family history of psychiatric disorder.\nDrug and alcohol usage.\n\nSuicidal ideation.\n\nMOQR>\n\nMCQ 3.347\n\nA 29-year-old woman has been treated with sertraline 50mg daily for the past\nfive weeks. She had initially presented with a four week history of bouts of\ncrying, insomnia, tiredness and weight loss as well as a general loss of interest\nin her family, friends and her job. Her symptoms had followed the break up\nof a longterm relationship and have improved with the treatment. She is now\ncomplaining of persistent abdominal discomfort over the past month. Which\none of the following is the best initial management strategy at this stage?\n\nSwitch to another selective serotonin reuptake inhibitor (SSRI) antidepressant.\nSwitch to a selective noradrenaline reuptake inhibitor (SNRI) antidepressant.\n. Switch to a tricyclic antidepressant.\n\nStop the sertraline immediately.\n\nAugment the sertraline with a mood stabiliser.\n\nMOQR>"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.345","duplicate_group_id":"exact-c2f56defe1e0","duplicate_sources":[{"record_id":"fafe81e297581704a708","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":372,"source_qid":"3.345"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"fafe81e297581704a708","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":372,"source_qid":"3.345","domain_hint":"Mixed/Unclassified","stem":"Ausiralian Medical Council\nSection 3 - Mental Health","options":{"A":"Reports of memory loss after ECT are exaggerated.","B":"ECT is superior to alternate therapies in most forms of depression.","C":"His family will also need to provide consent.","D":"ECT has good evidence for its efficacy from controlled trials.","E":"Consent will need to be obtained from a mental health tribunal or similar.\n\nMCQ 3.345\n\nSome factors increase the risk for more than one psychiatric disorder. Depression,\nanxiety, substance use and eating disorders may all have which one of the following\nas a risk factor?\n\nPerfectionism and obsessional traits.\nWorking in a bar (selling alcohol).\n\n. Sexual abuse in childhood.\n\nFamily history of autism.\n\nHistory of intellectual developmental delay.\n\nMOQOR>\n\nMCQ 3.346\n\nA 72-year-old man complains of waking in the middle of the night and not\nbeing able to get back to sleep. This has been happening now for months. He\nalso has a persistent headache, generalised aches and pains and constant\ntiredness. He has stopped going out and now spends most of his time at\nhome. Of the following, which one is the most important feature of the history\nto obtain from this patient?\n\nPrevious forensic history.\n\nAnxiety and panic attacks.\n\n. Family history of psychiatric disorder.\nDrug and alcohol usage.\n\nSuicidal ideation.\n\nMOQR>\n\nMCQ 3.347\n\nA 29-year-old woman has been treated with sertraline 50mg daily for the past\nfive weeks. She had initially presented with a four week history of bouts of\ncrying, insomnia, tiredness and weight loss as well as a general loss of interest\nin her family, friends and her job. Her symptoms had followed the break up\nof a longterm relationship and have improved with the treatment. She is now\ncomplaining of persistent abdominal discomfort over the past month. Which\none of the following is the best initial management strategy at this stage?\n\nSwitch to another selective serotonin reuptake inhibitor (SSRI) antidepressant.\nSwitch to a selective noradrenaline reuptake inhibitor (SNRI) antidepressant.\n. Switch to a tricyclic antidepressant.\n\nStop the sertraline immediately.\n\nAugment the sertraline with a mood stabiliser.\n\nMOQR>"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"c2f56defe1e08c3d3aaf2b1eaccb935bd3f4e707","duplicate_group_id":"exact-c2f56defe1e0","duplicate_sources":[{"record_id":"