INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('41c5bb90b84c96d31fc1','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','374','Mixed/Unclassified','A 58-year-old woman presents to a general practice seeking advice about her
35-year-old daughter who has just been notified that her long-standing application
to adopt a baby boy has been approved. However, her daughter and son-in-law
have insisted that the adoption is to be kept a secret within the family and that they
will never inform their child that he has been adopted. Which one of the following
would be the most appropriate advice to give to the prospective grandmother at
this time?','{"A":"As her daughter is not your patient, you cannot comment about her decision on\nthe grounds of confidentiality.","B":"Confirm that children who are told they are adopted will suffer lifelong shame and\nrejection.","C":"It is the parents’ responsibility alone to decide whether or not to inform the child,\nand it is none of the grandmother''s business.","D":"Inform her that once the child starts school, the child has an absolute right under\nFreedom of Information legislation to be informed, irrespective of what the parents\nwant.","E":"Encourage her to talk further with her daughter and son-in-law and to involve\nfamily support services before reaching a final decision.\n\nMCQ 3.354\n\nDelta-9-tetrahydrocannabinol (THC) is the primary psychoactive component of\ncannabis (marijuana). Which one of the following statements concerning the relationship\nbetween hydroponically grown cannabis and THC is correct? Hydroponically grown\ncannabis:\n. has no effect on THC concentration"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[374],"source_qid":"3.353","duplicate_group_id":"exact-ae00a2205dac","duplicate_sources":[{"record_id":"41c5bb90b84c96d31fc1","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":374,"source_qid":"3.353"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_multi_question_group","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','low','{"record_id":"41c5bb90b84c96d31fc1","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":374,"suppo