and distressed state. He is a boilermaker at a local engineering workshop and has just
witnessed a fellow worker being struck in the eyes by molten metal fragments during
an explosion at the factory that afternoon. The fellow worker has been rushed to the
City Eye Hospital. The man is saying that he is also blind and cannot see, but he was
not injured in the explosion and you can find no abnormalities on thorough physical
a examination. He also tells you that he feels responsible because he had been working
f nearby with an oxyacetylene flame but had left it unattended whilst he went to the
yy lavatory and this may have contributed to the explosion. Which one of the following
g is the most appropriate immediate psychological intervention for his anguish?','{"A":"Working through.","B":"Reality testing.","C":"Debriefing.","D":"D. Comforting.","E":"Problem solving.\n1,\n\nMCQ 3.357"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[375],"source_qid":"3.357","duplicate_group_id":"exact-9cbf95acb075","duplicate_sources":[{"record_id":"3ae4a061571af58ef795","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":375,"source_qid":"3.357"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','low','{"record_id":"3ae4a061571af58ef795","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":375,"supporting_pages":[375],"source_qid":"3.357","domain_hint":"Mixed/Unclassified","stem":"A 36-year-old man self-presents to the Emergency Department in a highly agitated\nand distressed state. He is a boilermaker at a local engineering workshop and has just\nwitnessed a fellow worker being struck in the eyes by molten metal fragments during\nan explosion at the factory that afternoon. The fellow worker has been rushed to the\nCity Eye Hospital. The man is saying that he is also blind and cannot see, but he was\nnot injured in the explosion and you can find no abnormalities on thorough physical\na examination. He also tells you that he feels responsible because he had been working\nf nearby with an oxyacetylene flame but had left it unattended whilst he went to the\nyy lavatory and this may have contributed to the explosion. Which one of the following\ng is the most appropriate immediate psychological intervention for his anguish?","options":{"A":"Working through.","B":"Reality testing.","C":"Debriefing.","D":"D. Comforting.","E":"Problem solving.\n1,\n\nMCQ 3.357"},"options_mode":"text","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"9cbf95acb0751ec1745d9309aab9d70b7845a6f9","duplicate_group_id":"exact-9cbf95acb075","duplicate_sources":[{"record_id":"3ae4a061571af58ef795","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":375,"source_qid":"3.357"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
