INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('c48c3f8e905f8d0ca9e4','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','376','Mixed/Unclassified','Australian Medical Council
Section 3 - Mental Health
A. Hypnogogic hallucinations.
B. Major depression.
C. Rapid eye movement sleep disorder.
D. Normal grief.
E. Paroxysmal nocturnal tachycardia.
MCQ 3.359
A 29-year-old woman presents for review of her 2-week-old baby. This is her first child.
She has moved from interstate with her husband since the birth, to stay with her own
mother, who is helping to care for the infant for the next few weeks. The woman
tells you that she had been taking some medication for ‘nerves’ prior to becoming
pregnant, but that she had stopped it recently against the advice of the psychiatrist
that had been treating her. Since the birth, she has been having racing thoughts,
sleeping poorly and complains of being ‘overtired’ and exhausted because of her
desire to breastfeed-on-demand. Her baby had been delivered vaginally at term
after an apparently uneventful pregnancy, but she tells you that during the pregnancy
she had fleeting thoughts that her baby was ‘special’ and may be ‘the Son of God!
and that she herself may be ‘the Virgin Mary’. These thoughts have become more
persistent postpartum, but she dismisses them as being due to her ‘imagination
playing tricks’ with her because of sleep deprivation and the excitement of having
her first child. Although she is willing to resume taking medication, she will only take
something which will allow her to continue breastfeeding. Which one of the following
is the most appropriate initial medication option?
A. Cabergoline.
B. Sodium valproate.
C. Olanzapine.
D. Lithium carbonate.
E. Diazepam.
MCQ 3.360
A 7-year-old boy whose parents have divorced recently is brought to the clinic by his
mother. The mother states that the boy does not seem to listen to what she says, does
not finish his chores and will not remain at the table for meals, is always fidgeting and
interrupting her telephone conversations. The boy has just started at a new school.
The mother says the boy''s behaviour is just like her brother''s when he was younger.
When you talk with the boy he only gives you minimal responses and quite often
just shrugs his shoulders as if to say ‘| don''t know’. After completing the history from
the mother, which one of the following would be the most appropriate next step in
management?','{"A":". Obtain collateral history from his father.\nObtain behavioural rating scales.","B":". Arrange vision and hearing assessments.","C":". Arrange for classroom observation.","D":"Arrange psychometric testing.","E":"MOQ 2 >"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[376],"source_qid":"3.359","duplicate_group_id":"exact-1d7407c694fe","duplicate_sources":[{"record_id":"c48c3f8e905f8d0ca9e4","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":376,"source_qid":"3.359"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"c48c3f8e905f8d0ca9e4","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":376,"supporting_pages":[376],"source_qid":"3.359","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 3 - Mental Health\nA. Hypnogogic hallucinations.\nB. Major depression.\nC. Rapid eye movement sleep disorder.\nD. Normal grief.\nE. Paroxysmal nocturnal tachycardia.\nMCQ 3.359\nA 29-year-old woman presents for review of her 2-week-old baby. This is her first child.\nShe has moved from interstate with her husband since the birth, to stay with her own\nmother, who is helping to care for the infant for the next few weeks. The woman\ntells you that she had been taking some medication for ‘nerves’ prior to becoming\npregnant, but that she had stopped it recently against the advice of the psychiatrist\nthat had been treating her. Since the birth, she has been having racing thoughts,\nsleeping poorly and complains of being ‘overtired’ and exhausted because of her\ndesire to breastfeed-on-demand. Her baby had been delivered vaginally at term\nafter an apparently uneventful pregnancy, but she tells you that during the pregnancy\nshe had fleeting thoughts that her baby was ‘special’ and may be ‘the Son of God!\nand that she herself may be ‘the Virgin Mary’. These thoughts have become more\npersistent postpartum, but she dismisses them as being due to her ‘imagination\nplaying tricks’ with her because of sleep deprivation and the excitement of having\nher first child. Although she is willing to resume taking medication, she will only take\nsomething which will allow her to continue breastfeeding. Which one of the following\nis the most appropriate initial medication option?\nA. Cabergoline.\nB. Sodium valproate.\nC. Olanzapine.\nD. Lithium carbonate.\nE. Diazepam.\nMCQ 3.360\nA 7-year-old boy whose parents have divorced recently is brought to the clinic by his\nmother. The mother states that the boy does not seem to listen to what she says, does\nnot finish his chores and will not remain at the table for meals, is always fidgeting and\ninterrupting her telephone conversations. The boy has just started at a new school.\nThe mother says the boy''s behaviour is just like her brother''s when he was younger.\nWhen you talk with the boy he only gives you minimal responses and quite often\njust shrugs his shoulders as if to say ‘| don''t know’. After completing the history from\nthe mother, which one of the following would be the most appropriate next step in\nmanagement?","options":{"A":". Obtain collateral history from his father.\nObtain behavioural rating scales.","B":". Arrange vision and hearing assessments.","C":". Arrange for classroom observation.","D":"Arrange psychometric testing.","E":"MOQ 2 >"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","pregnan"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"1d7407c694fe6588713aeb3972a630847d374fef","duplicate_group_id":"exact-1d7407c694fe","duplicate_sources":[{"record_id":"c48c3f8e905f8d0ca9e4","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":376,"source_qid":"3.359"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
