INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('82b25401e1f88dd92fde','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','380','Mixed/Unclassified','C. Zopiclone.
D. Additional risperidone.
E. Amitriptyline.
MCQ 3.371
A 40-year-old high school teacher presents with increasing worry about intermittent
left lower abdominal pain, epigastric bloating and fluctuating constipation and
diarrhoea. Her symptoms began after a stressful parent-teacher meeting, during
which she was confronted and abused by an irate parent, about three months ago.
She has had similar episodes in the past since her adolescence and reports that
although the pain is relieved by defaecation, she is afraid that she may have bowel |
| cancer. On examination she is tender in her left iliac fossa over her sigmoid colon.
There is no family history of bowel disease, no weight loss, fever or rectal bleeding. :
Which one of the following is most likely to improve her overall symptoms and general |
well-being?','{"A":"Aloe vera.","B":"Acupuncture. ;","C":"High fibre diet.","D":"Amitriptyline.","E":"Fluoxetine.\n\n362 ;"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[380],"source_qid":"3.369","duplicate_group_id":"exact-ede7b872d47a","duplicate_sources":[{"record_id":"82b25401e1f88dd92fde","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":380,"source_qid":"3.369"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','low','{"record_id":"82b25401e1f88dd92fde","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":380,"supporting_pages":[380],"source_qid":"3.369","domain_hint":"Mixed/Unclassified","stem":"C. Zopiclone.\nD. Additional risperidone.\nE. Amitriptyline.\nMCQ 3.371\nA 40-year-old high school teacher presents with increasing worry about intermittent\nleft lower abdominal pain, epigastric bloating and fluctuating constipation and\ndiarrhoea. Her symptoms began after a stressful parent-teacher meeting, during\nwhich she was confronted and abused by an irate parent, about three months ago.\nShe has had similar episodes in the past since her adolescence and reports that\nalthough the pain is relieved by defaecation, she is afraid that she may have bowel |\n| cancer. On examination she is tender in her left iliac fossa over her sigmoid colon.\nThere is no family history of bowel disease, no weight loss, fever or rectal bleeding. :\nWhich one of the following is most likely to improve her overall symptoms and general |\nwell-being?","options":{"A":"Aloe vera.","B":"Acupuncture. ;","C":"High fibre diet.","D":"Amitriptyline.","E":"Fluoxetine.\n\n362 ;"},"options_mode":"text","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"ede7b872d47a49fffb6a61b9c167efa39258970f","duplicate_group_id":"exact-ede7b872d47a","duplicate_sources":[{"record_id":"82b25401e1f88dd92fde","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":380,"source_qid":"3.369"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
