INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('bca8ec4fb765d2d3f568','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','381','Mixed/Unclassified','wOs+0O4¢O0UN
MCQ 3.372
A 62-year-old-man presents with sleep-onset insomnia which has been present ‘for
years’ but is slowly getting worse. He says that after he gets into bed at night he is
kept awake by an unpleasant nonspecific discomfort in his legs which is a mixture
of ‘tingling, burning and crawling’ of the skin from his thighs to his feet. The sensory
symptoms are relieved only by moving his legs in the bed or by getting up and walking
around the house. His sleep onset is deferred to the early hours of the morning and
he is left feeling tired and washed out by mid-afternoon. He smokes a pipe in the
evenings and has a glass of wine with his evening meal. He has had chronic lower
back pain for which he takes celecoxib 200mg daily. His body mass index (BMI) is
26. He has some lower limb varicosities. Which one of the following is the most likely
explanation of his symptoms?
. Peripheral neuropathy.
\liofemoral arteriovascular disease.
. Restless legs syndrome.
. Akathisia.
Adult attention deficit hyperactivity disorder.
MOOD
MCQ 3.373
A 23-year-old man has had longterm treatment with risperidone 4mg daily for
schizophrenia. Although he does not have a sexual partner he has had persistent
ejaculatory problems and has recently developed a whitish discharge from one of
his breasts. He is requesting a change in his medication, but he has ongoing ideas
of reference, particularly from television news broadcasts, and he has constant
background whispering voices. To minimise the risk of relapse or a worsening of his
mental state, which one of the following management strategies is the most likely to
be effective?','{"A":"Add Risperdal Consta® depot extended release injection fortnightly, and reduce\nthe oral risperidone over six weeks.","B":"Add amisulpride, and reduce the risperidone over four weeks.","C":"Add clozapine, and continue risperidone until the clozapine level is within the ther-\napeutic range and then cease risperidone.","D":"Add quetiapine, and begin tapering the risperidone after two weeks.","E":"Stop the risperidone, and switch immediately to olanzapine.\n\nMCQ 3.374\n\nA 24-year-old-man has been brought to the Emergency Department by the police\nafter he had trashed his flat while searching for ‘hidden cameras’. He is known to use\nhydroponic marijuana and to inject amphetamines. The police say that they had to\nuse pepper spray because he was so aggressive and violent when they arrived at\nhis flat. He is handcuffed but is highly agitated, shouting, swearing and apparently\ntalking ‘to aliens’. After attempts at verbal de-escalation have failed, which one of\nthe following would be the most appropriate initial choice of medication and route\nof administration for his level of arousal?\n\nAusiralian Medical Council\n\nSection 3- Mental Health"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.372","duplicate_group_id":"exact-a8052ddbaeac","duplicate_sources":[{"record_id":"bca8ec4fb765d2d3f568","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":381,"source_qid":"3.372"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"bca8ec4fb765d2d3f568","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":381,"source_qid":"3.372","domain_hint":"Mixed/Unclassified","stem":"wOs+0O4¢O0UN\nMCQ 3.372\nA 62-year-old-man presents with sleep-onset insomnia which has been present ‘for\nyears’ but is slowly getting worse. He says that after he gets into bed at night he is\nkept awake by an unpleasant nonspecific discomfort in his legs which is a mixture\nof ‘tingling, burning and crawling’ of the skin from his thighs to his feet. The sensory\nsymptoms are relieved only by moving his legs in the bed or by getting up and walking\naround the house. His sleep onset is deferred to the early hours of the morning and\nhe is left feeling tired and washed out by mid-afternoon. He smokes a pipe in the\nevenings and has a glass of wine with his evening meal. He has had chronic lower\nback pain for which he takes celecoxib 200mg daily. His body mass index (BMI) is\n26. He has some lower limb varicosities. Which one of the following is the most likely\nexplanation of his symptoms?\n. Peripheral neuropathy.\n\\liofemoral arteriovascular disease.\n. Restless legs syndrome.\n. Akathisia.\nAdult attention deficit hyperactivity disorder.\nMOOD\nMCQ 3.373\nA 23-year-old man has had longterm treatment with risperidone 4mg daily for\nschizophrenia. Although he does not have a sexual partner he has had persistent\nejaculatory problems and has recently developed a whitish discharge from one of\nhis breasts. He is requesting a change in his medication, but he has ongoing ideas\nof reference, particularly from television news broadcasts, and he has constant\nbackground whispering voices. To minimise the risk of relapse or a worsening of his\nmental state, which one of the following management strategies is the most likely to\nbe effective?","options":{"A":"Add Risperdal Consta® depot extended release injection fortnightly, and reduce\nthe oral risperidone over six weeks.","B":"Add amisulpride, and reduce the risperidone over four weeks.","C":"Add clozapine, and continue risperidone until the clozapine level is within the ther-\napeutic range and then cease risperidone.","D":"Add quetiapine, and begin tapering the risperidone after two weeks.","E":"Stop the risperidone, and switch immediately to olanzapine.\n\nMCQ 3.374\n\nA 24-year-old-man has been brought to the Emergency Department by the police\nafter he had trashed his flat while searching for ‘hidden cameras’. He is known to use\nhydroponic marijuana and to inject amphetamines. The police say that they had to\nuse pepper spray because he was so aggressive and violent when they arrived at\nhis flat. He is handcuffed but is highly agitated, shouting, swearing and apparently\ntalking ‘to aliens’. After attempts at verbal de-escalation have failed, which one of\nthe following would be the most appropriate initial choice of medication and route\nof administration for his level of arousal?\n\nAusiralian Medical Council\n\nSection 3- Mental Health"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","treatment"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"a8052ddbaeac16af4ebb1202ab72e89b35e14c8f","duplicate_group_id":"exact-a8052ddbaeac","duplicate_sources":[{"record_id":"bca8ec4fb765d2d3f568","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":381,"source_qid":"3.372"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
