INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ef66a043a57ce28adf63','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','382','Mixed/Unclassified','Australian Medical Council
Section 3- Mental Health
A. Diazepam syrup.
B. Intramuscular diazepam.
C. Intravenous diazepam.
D. Intramuscular midazolam.
E. Intramuscular droperidol.
MCQ 3.375
A 65-year-old woman is admitted to hospital with sudden onset of agitation, confusion
and fever for the past 12 months. She has been taking sertraline for depression. She
has also been taking some over-the-counter medications for the last week. Her BP
is 180/80mmHg, temperature 37.8°C, pulse 110/min and regular. She has a coarse
tremor of both hands, muscle tone is normal but reflexes are generally increased. The
optic fundi show grade Il hypertensive changes. Her full blood count, chest X-ray,
urine examination and serum creatine kinase (CK) are all normal. Which one of the
following is the most likely diagnosis?
A. Neuroleptic malignant syndrome.
B. Serotonin syndrome.
C. Herpes encephalitis.
D. Systemic sepsis.
E. Hypertensive encephalopathy.
MCQ 3.376
An 80-year-old woman presents with a history of recurrent falls. She lives at home
alone. She has hypertension treated with perindopril 5mg daily. Over the past six
weeks she has developed cognitive impairment for which she receives haloperidol
Img nocte to manage nocturnal wandering. Her Mini-Mental State Examination
(MMSE) score is 24/30. Her BP and pulse readings are BP 154/6é6mmHg, pulse 80/
min regular (supine), BP 136/60mmHg, 84/min (standing). She has some involuntary
movements of her face and tongue, a slow small-paced gait, and increased muscle
tone in all limbs. Which one of the following is the most appropriate next step in
management?
. Commence levodopa.
Commence benztropine mesylate.
. Commence selegiline.
. Cease perindopril.
Cease haloperidol.
MOQ F >
MCQ 3.377
Relatives report a gradual decline in memory and self-care skills in a 70-year-old
woman over several years. Examination shows that she is disoriented in time, has poor
short-term memory, impaired planning, arithmetic and visuospatial skills. There are no
other abnormal clinical or imaging findings. Which one of the following is the most
likely diagnosis?','{"A":"SECTION 3: POPULATION,\nCOMMUNITY HEALTH AND ETHICS","B":"General Practice / Public Health","C":"3.379-3.411","D":"PG5-PHE\nSystem 21","E":"May include: community, family and hospital care, general practice, demography\nstatistics, public health, informatics, social and preventive medicine, forensic an\nlegal medicine, health economics and ethics."}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[382,384],"source_qid":"3.375","duplicate_group_id":"exact-3116af5c10ee","duplicate_sources":[{"record_id":"ef66a043a57ce28adf63","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":382,"source_qid":"3.375"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"ef66a043a57ce28adf63","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":382,"supporting_pages":[382,384],"source_qid":"3.375","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 3- Mental Health\nA. Diazepam syrup.\nB. Intramuscular diazepam.\nC. Intravenous diazepam.\nD. Intramuscular midazolam.\nE. Intramuscular droperidol.\nMCQ 3.375\nA 65-year-old woman is admitted to hospital with sudden onset of agitation, confusion\nand fever for the past 12 months. She has been taking sertraline for depression. She\nhas also been taking some over-the-counter medications for the last week. Her BP\nis 180/80mmHg, temperature 37.8°C, pulse 110/min and regular. She has a coarse\ntremor of both hands, muscle ton