travelling to Thailand for a stay of six weeks, visiting both city and country areas,
including trekking in the north near the Thai-Burmese border. Apart from advice about
avoiding mosquito bites (special care between dusk and daylight, wearing long sleeves
and trousers outside, use of repellent creams and sprays, use of screened windows and
mosquito netting at night), which one of the following would be the most appropriate
advice for chemoprophylaxis?','{"A":"Quinine from a week before arrival until six weeks after return.","B":"Chloroquine from time of arrival until time of return.","C":"Doxycycline from two days before arrival until two weeks after return.","D":"Albendazole from a week before arrival until six weeks after return.","E":"No additional chemoprophylaxis is required.\n\nFETE EEE Senn\nMCQ 3.394"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[388],"source_qid":"3.392","duplicate_group_id":"exact-7d8ef172f5af","duplicate_sources":[{"record_id":"4e0179d9c55ff91b3e08","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":388,"source_qid":"3.392"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','medium','{"record_id":"4e0179d9c55ff91b3e08","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":388,"supporting_pages":[388],"source_qid":"3.392","domain_hint":"Mixed/Unclassified","stem":"A 25-year-old man presents for travel advice about malaria prevention. He will be\ntravelling to Thailand for a stay of six weeks, visiting both city and country areas,\nincluding trekking in the north near the Thai-Burmese border. Apart from advice about\navoiding mosquito bites (special care between dusk and daylight, wearing long sleeves\nand trousers outside, use of repellent creams and sprays, use of screened windows and\nmosquito netting at night), which one of the following would be the most appropriate\nadvice for chemoprophylaxis?","options":{"A":"Quinine from a week before arrival until six weeks after return.","B":"Chloroquine from time of arrival until time of return.","C":"Doxycycline from two days before arrival until two weeks after return.","D":"Albendazole from a week before arrival until six weeks after return.","E":"No additional chemoprophylaxis is required.\n\nFETE EEE Senn\nMCQ 3.394"},"options_mode":"text","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["prophyl","screen"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"7d8ef172f5af16b5142fb26f6b6bac63fda54d7a","duplicate_group_id":"exact-7d8ef172f5af","duplicate_sources":[{"record_id":"4e0179d9c55ff91b3e08","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":388,"source_qid":"3.392"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.