INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('89b7c946490c131473ce','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','390','Mixed/Unclassified','Australia Medical Council
. Adsorbed diphtheria and tetanus (ADT) vaccine.
. Tetanus toxoid and tetanus immune globulin (TIG).
. Tetanus immune globulin (TIG).
. Penicillin G and tetanus immune globulin (TIG).
. Penicillin G alone.
MCQ 3.399
Which one of the following factors is most closely associated with the lowest mortality
rates and maximal survival in the elderly?
. Financial independence.
. The presence of living children.
. Marital status.
. Peer group support.
. Living in one’s own home.
MCQ 3.400
Doctors often rely on printed patient information material to augment verbal
instructions or explanations during the consultation. Which one of the following
aspects of literacy is the most crucial in relation to patient education capacity when
receiving printed material?','{"A":"Reading ability.","B":"Writing ability.","C":"Spelling ability.","D":"Reading comprehension.","E":"Ability to read out loud.\n\nOOO OOOO\n\nMCQ 3.401\n\nA junior medical colleague has been attending a course on medical ethics and seeks\nyour understanding of a term encountered in the course. He presented the following\ncase and was asked to describe the term ‘conspiracy of silence’.\n\nA 78-year-old woman has been diagnosed with small cell carcinoma of the (lt)\nlung with probable liver and bone metastases. Prior to undergoing the diagnostic\ntests, the patient stated that she did not wish to be told of any serious diagnosis\nand! also stated that her family were not be told of her condition. She wants to\n\nreturn home to the care of her trusted general practitioner.\n\nWhich one of the following best describes the ‘conspiracy of silence’ in the case\npresented?\n\n. The doctor agrees to give false information to the relatives about the diagnosis.\n\n. The doctor provides the patient with an overoptimistic prognosis for her\ncondition.\n\n. The doctor does not provide sufficient detail to her general practitioner to continue\nher care.\n\n. The doctor agrees not to tell the patient her diagnosis.\n. The doctor agrees not to tell the family of her prognosis."}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.399","duplicate_group_id":"exact-fe0581d29c38","duplicate_sources":[{"record_id":"89b7c946490c131473ce","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":390,"source_qid":"3.399"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_ve