e’ in the case\npresented?\n\n. The doctor agrees to give false information to the relatives about the diagnosis.\n\n. The doctor provides the patient with an overoptimistic prognosis for her\ncondition.\n\n. The doctor does not provide sufficient detail to her general practitioner to continue\nher care.\n\n. The doctor agrees not to tell the patient her diagnosis.\n. The doctor agrees not to tell the family of her prognosis."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["vaccin"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"fe0581d29c38199d67c6f68863f075fbfadb631e","duplicate_group_id":"exact-fe0581d29c38","duplicate_sources":[{"record_id":"89b7c946490c131473ce","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":390,"source_qid":"3.399"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=ex