l therapy is effective in reversing the conviction of belonging\nto the opposite sex.\n375"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["diabetes"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","record_type":"text_mcq","options_mode":"text","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"a432e0ed30468d4d6eaf3e668f4e18feb1afd092","duplicate_group_id":"exact-a432e0ed3046","duplicate_sources":[{"record_id":"e378de33d42fabcd4419","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":393,"source_qid":"3.409"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
