INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('964f835c4f8563a2535a','AMEDEX 2025 CVS (1).pdf','147','Cardiology','A 70-year-old man, farmer by profession,
presents to the Emergency Department after he
experienced chest pain of 20 minutes duration
following physical activity. When the pain
Started, he took 3 puffs of glyceryl trinitrate but
there was no relief. In the Emergency
Department though, the pain alleviated with
oxygen. On further questioning, you realize that
he is on aspirin, metoprolol and sublingual
glyceryl trinitrate spray on an ‘as needed’ basis.
During the past 6 months, he has had only 3
episodes of chest pain subsided just by rest. He
saw his GP 6 months ago when he received his
last prescription. Which one of the following is
the most likely explanation of failure of glyceryl
trinitrate to relieve his symptoms?','{"A":"Onset of unstable angina.","B":"Nitrate tolerance.","C":"Reduced drug potency.","D":"Poor absorption through the\nmouth.","E":"Onset of myocardial infarction."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-5a4e191915f0","duplicate_sources":[{"record_id":"964f835c4f8563a2535a","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":147,"source_qid":null},{"record_id":"02de12d2673bef7a06b3","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":27,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"964f835c4f8563a2535a","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_year":2025,"source_page":147,"source_qid":null,"domain_hint":"Cardiology","stem":"A 70-year-old man, farmer by profession,\npresents to the Emergency Department after he\nexperienced chest pain of 20 minutes duration\nfollowing physical activity. When the pain\nStarted, he took 3 puffs of glyceryl trinitrate but\nthere was no relief. In the Emergency\nDepartment though, the pain alleviated with\noxygen. On further questioning, you realize that\nhe is on aspirin, metoprolol and sublingual\nglyceryl trinitrate spray on an ‘as needed’ basis.\nDuring the past 6 months, he has had only 3\nepisodes of chest pain subsided just by rest. He\nsaw his GP 6 months ago when he received his\nlast prescription. Which one of the following is\nthe most likely explanation of failure of glyceryl\ntrinitrate to relieve his symptoms?","options":{"A":"Onset of unstable angina.","B":"Nitrate tolerance.","C":"Reduced drug potency.","D":"Poor absorption through the\nmouth.","E":"Onset of myocardial infarction."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["duration"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"five_block_inferred","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"5a4e191915f0482d2206eb877e4bd6632993f42c","duplicate_group_id":"exact-5a4e191915f0","duplicate_sources":[{"record_id":"964f835c4f8563a2535a","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":147,"source_qid":null},{"record_id":"02de12d2673bef7a06b3","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":27,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
