INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a7c63d384727fa8047e4','AMEDEX 2025 CVS (1).pdf','210','Cardiology','A 59-year-old man in brought to the
emergency department of a tertiary hospital
with compressing chest pain that has started
30 minutes ago.The pain is central in location
and radiates to his jaw and left arm. A 12-lead
